#!/usr/bin/env python3
"""
Passo 7 - Mover faixa para album + Criar album vazio (Player3D / Galeria3D).

Aplica de uma vez, em 7 arquivos Java + 4 arquivos de recurso (1 novo
arquivo Java + 4 recursos modificados), a implementacao completa de:
  - "Criar album": item no menu overflow (3 pontinhos), logo abaixo de
    Configuracoes. Cria uma pasta vazia em Music/<nome>.
  - "Mover para album": item no menu de selecao multipla (dentro de um
    album/artista/playlist/musicas aberto). Se o usuario nao estiver no
    filtro Albuns, forca a navegacao ate la (selecao preservada) para
    escolher o album destino de verdade (pasta fisica real). Move os
    arquivos fisicamente, com o caminho certo por versao do Android
    (Scoped Storage em SDK 29+, incluindo pedido de permissao extra em
    SDK 30-32 se necessario).

Rode este script de dentro de ~/Galeria3D (raiz do repo clonado).
Idempotente: pode rodar 2x sem quebrar nada.
Cada arquivo tocado ganha um .bak antes de ser sobrescrito.
"""

import base64
import io
import os
import shutil
import sys
import tarfile

# Caminho -> nome do arquivo dentro do payload (relativo a raiz do repo).
FILES = {
    "app/src/main/java/com/android/gallery3d/data/MediaObject.java": "MediaObject.java",
    "app/src/main/java/com/android/gallery3d/data/LocalAudio.java": "LocalAudio.java",
    "app/src/main/java/com/android/gallery3d/data/LocalAlbum.java": "LocalAlbum.java",
    "app/src/main/java/com/android/gallery3d/app/AlbumPage.java": "AlbumPage.java",
    "app/src/main/java/com/android/gallery3d/app/AlbumSetPage.java": "AlbumSetPage.java",
    "app/src/main/java/com/android/gallery3d/ui/MenuExecutor.java": "MenuExecutor.java",
    "app/src/main/java/com/android/gallery3d/util/MoveToAlbumHelper.java": "MoveToAlbumHelper.java",
    "app/src/main/res/menu/operation.xml": "operation.xml",
    "app/src/main/res/menu/albumset.xml": "albumset.xml",
    "app/src/main/res/values/strings.xml": "strings.xml",
    "app/src/main/res/values-pt/strings.xml": "strings-pt.xml",
}

PAYLOAD_B64 = ""


def load_payload():
    raw = base64.b64decode(PAYLOAD_B64)
    return tarfile.open(fileobj=io.BytesIO(raw), mode="r:gz")


def already_applied():
    path = "app/src/main/java/com/android/gallery3d/app/AlbumPage.java"
    if not os.path.isfile(path):
        return False
    with open(path, "r", encoding="utf-8") as f:
        return "startMoveToAlbumFlow" in f.read()


def main():
    if not os.path.isdir("app/src/main/java/com/android/gallery3d"):
        print("ERRO: nao encontrei app/src/main/java/com/android/gallery3d")
        print("Rode este script de dentro da pasta raiz do repo (~/Galeria3D).")
        sys.exit(1)

    if already_applied():
        print("Passo 7 ja aplicado anteriormente (AlbumPage.java ja tem")
        print("startMoveToAlbumFlow) — nada a fazer (script e idempotente).")
        sys.exit(0)

    tar = load_payload()
    members = {m.name.lstrip("./"): m for m in tar.getmembers()}

    for repo_path, payload_name in FILES.items():
        if payload_name not in members:
            print(f"ERRO interno: payload nao contem {payload_name}")
            sys.exit(1)

    backups = []
    try:
        for repo_path, payload_name in FILES.items():
            new_content = tar.extractfile(members[payload_name]).read()

            if os.path.isfile(repo_path):
                backup_path = repo_path + ".bak"
                shutil.copyfile(repo_path, backup_path)
                backups.append(backup_path)
                print(f"Backup criado: {backup_path}")
            else:
                os.makedirs(os.path.dirname(repo_path), exist_ok=True)

            with open(repo_path, "wb") as f:
                f.write(new_content)
            print(f"Atualizado: {repo_path}")

    except Exception as e:
        print(f"ERRO durante a aplicacao: {e}")
        print("Arquivos ja copiados tem backup .bak ao lado, revise manualmente se necessario.")
        sys.exit(1)

    print()
    print("Passo 7 aplicado com sucesso.")
    print()
    print("O que foi feito:")
    print("- 'Criar album': menu overflow (3 pontinhos), logo abaixo de")
    print("  Configuracoes. Cria uma pasta vazia em Music/<nome digitado>.")
    print("  IMPORTANTE: uma pasta recem-criada so aparece como album na")
    print("  grade depois que a 1a faixa for movida para dentro dela --")
    print("  isso e uma limitacao do MediaStore (albuns sao derivados de")
    print("  arquivos de midia existentes), nao um bug. O app avisa isso")
    print("  no Toast de sucesso.")
    print("- 'Mover para album': dentro de um album/artista/playlist/")
    print("  musicas aberto, selecione faixas (toque longo) e toque no")
    print("  novo icone no menu de selecao. Se voce nao estiver no filtro")
    print("  Albuns, o app leva voce ate la automaticamente (com a selecao")
    print("  preservada) para escolher o album destino real. Depois pede")
    print("  confirmacao e move os arquivos de fato.")
    print()
    print("Proximo passo: recompile o app e teste os dois fluxos:")
    print("1. Criar um album vazio pelo menu overflow")
    print("2. Selecionar 1+ faixas em qualquer filtro e mover para um")
    print("   album existente")


if __name__ == "__main__":
    main()
